          this.orgContent = content
        }
        this.diffEditContent = this.code
      }
      this.showDiff = !this.showDiff
    },
    async loadDiffInfo() {
      try {
        this.loadingStats = true
        if (this.file) {
          const res = await this.$api.files.diff({ path: this.file, content: this.code })
          this.stats = res.stats || 'File changes'
          this.lastModification = res.last_modification
          this.fileSize = res.size
          if (!this.orgContent) {
            const { content } = await this.$api.files.read(this.file)
            this.orgContent = content
          }
          this.calculateDiffPercentages()
        }
      } finally {
        this.loadingStats = false
      }
    },
    onEdit() {
      if (this.editMode) {
        this.cancelEdit()
        return
      }
      this.editContent = this.code
      this.editMode = true
      this.showDiff = false
    },
    cancelEdit() {
      this.editMode = false
      this.editContent = null
    },
    onEditorChange(value) {
      this.editContent = value
    },
    applyMessageChange() {
      this.$emit('message-change', { orgContent: this.code, newContent: this.editContent })
      this.cancelEdit()
    },
    async saveDiffEdit() {
      this.triggerSaveAnimation()
      this.$emit('save-file', { file: this.file, content: this.diffEditContent })
      this.showDiff = false
      await this.loadDiffInfo()
      this.showResetButton = true
    },
    async saveToFile() {
      this.triggerSaveAnimation()
      const content = this.editMode ? this.editContent : this.code
      this.$emit('save-file', { file: this.file, content })
      if (this.editMode) {
        this.cancelEdit()
      }
      await this.loadDiffInfo()
      this.showResetButton = true
    },
    triggerSaveAnimation() {
      this.isSaving = true
      setTimeout(() => {
        this.isSaving = false
      }, 800)
    },
    runCommand() {
      this.$storex.api.apps.runScript(this.code)
    },
    onCopy() {
      this.$ui.copyTextToClipboard(this.code)
    },
    createSubTask() {
      const content = [
        '```' + this.fileLanguage + ' ' + this.file,
        this.code,
        '```'
      ].join('\n')
      this.$emit('sub-task', { file: this.file, content })
    },
    saveScrollPosition() {
      const viewCode = this.$el?.querySelector('.view-code')
      if (!viewCode) return
      this.prevScrollTop = viewCode.scrollTop
      const distanceFromBottom = viewCode.scrollHeight - viewCode.scrollTop - viewCode.clientHeight
      this.isAtBottom = distanceFromBottom <= 40
    },
    openResetModal() {
      this.showResetConfirm = true
    },
    closeResetModal() {
      this.showResetConfirm = false
    },
    async confirmReset() {
      try {
        await this.$api.files.reset({ path: this.file })
        this.$ui.toast.success('File reset successfully')
        this.showResetButton = false
        this.closeResetModal()
        await this.loadDiffInfo()
      } catch (error) {
        this.$ui.toast.error('Failed to reset file')
        console.error(error)
      }
    },
    applyPatch() {
      this.$projects.applyPatch({ patch: this.code })
    }
  }
}
</script>
